-- TeknoSepet eğitim veritabanı (kurgusal). SSMS'te açın ve F5 ile çalıştırın.
-- SQL Server 2016+ / Express / LocalDB ile uyumludur.
IF DB_ID(N'TeknoSepetDB') IS NULL CREATE DATABASE TeknoSepetDB;
GO
USE TeknoSepetDB;
GO
IF OBJECT_ID('dbo.vw_AylikSatis') IS NOT NULL DROP VIEW dbo.vw_AylikSatis;
IF OBJECT_ID('dbo.Siparisler') IS NOT NULL DROP TABLE dbo.Siparisler;
IF OBJECT_ID('dbo.Urunler') IS NOT NULL DROP TABLE dbo.Urunler;
IF OBJECT_ID('dbo.Magazalar') IS NOT NULL DROP TABLE dbo.Magazalar;
IF OBJECT_ID('dbo.Kanallar') IS NOT NULL DROP TABLE dbo.Kanallar;
GO
CREATE TABLE dbo.Kanallar (KanalID varchar(5) PRIMARY KEY, KanalAdi nvarchar(50), KanalGrubu nvarchar(20));
CREATE TABLE dbo.Magazalar (MagazaID varchar(5) PRIMARY KEY, MagazaAdi nvarchar(60), Sehir nvarchar(30), Bolge nvarchar(40), MagazaTipi nvarchar(10), AcilisTarihi date);
CREATE TABLE dbo.Urunler (UrunID varchar(5) PRIMARY KEY, UrunAdi nvarchar(60), Kategori nvarchar(30), AltKategori nvarchar(20), Marka nvarchar(30), ListeFiyati decimal(12,2), BirimMaliyet decimal(12,2), Durum nvarchar(10));
CREATE TABLE dbo.Siparisler (SatisID varchar(10) PRIMARY KEY, SiparisNo varchar(20), Tarih date, MusteriID varchar(6), UrunID varchar(5) REFERENCES dbo.Urunler(UrunID), MagazaID varchar(5) REFERENCES dbo.Magazalar(MagazaID), KanalID varchar(5) REFERENCES dbo.Kanallar(KanalID), Adet int, BirimFiyat decimal(12,2), IndirimOrani decimal(5,2), IadeMi nvarchar(5), OdemeTipi nvarchar(30));
GO
GO
GO
GO
GO
CREATE VIEW dbo.vw_AylikSatis AS
SELECT DATEFROMPARTS(YEAR(s.Tarih), MONTH(s.Tarih), 1) AS Ay, m.Bolge, u.Kategori,
       SUM(s.Adet) AS ToplamAdet,
       SUM(s.Adet * s.BirimFiyat * (1 - s.IndirimOrani)) AS NetTutar
FROM dbo.Siparisler s JOIN dbo.Urunler u ON u.UrunID = s.UrunID JOIN dbo.Magazalar m ON m.MagazaID = s.MagazaID
WHERE s.IadeMi = N'Hayır'
GROUP BY DATEFROMPARTS(YEAR(s.Tarih), MONTH(s.Tarih), 1), m.Bolge, u.Kategori;
GO
SELECT COUNT(*) AS SiparisSatiri FROM dbo.Siparisler;  -- beklenen: 6004
